// Des: Read a PDF ToUnicode CMap and map font codes to text
// Flo: find codespace width > parse bfchar and bfrange blocks > code to UTF-8 map > decode byte strings
// I/O: CMap stream bytes (caller) > Cmap (code width, map); decode(bytes) appends UTF-8
// ===================================================================
const std = @import("std"); const mem2 = std.mem; const obje = @import("pa-pdfz-obje.zig");
const CF = .{ .entz = 120000, .rngz = 65535 };
pub const Cmap = struct { cswz: u8 = 0, map: std.AutoHashMapUnmanaged(u32, []const u8) = .empty };
fn hexzNext(srcz: []const u8, ind3: *usize) ?[]const u8 { var kixz = ind3.*; while (kixz < srcz.len and srcz[kixz] != '<') { if (srcz[kixz] == 'e' and mem2.startsWith(u8, srcz[kixz..], "end")) return null; kixz += 1; } if (kixz >= srcz.len) return null; const cloz = mem2.findScalarPos(u8, srcz, kixz, '>') orelse return null; const tex2 = srcz[kixz + 1 .. cloz]; ind3.* = cloz + 1; return tex2; }
fn hexzNumb(tex2: []const u8) u32 { var val2: u32 = 0; for (tex2) |chr2| { const digz = std.fmt.charToDigit(chr2, 16) catch continue; val2 = (val2 << 4) | digz; } return val2; }
fn unizEncz(aren: std.mem.Allocator, tex2: []const u8, add: u32) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var uni2: [16]u16 = undefined; var con2: usize = 0; var kixz: usize = 0; if (tex2.len <= 2) { uni2[0] = @intCast(hexzNumb(tex2) + add); con2 = 1; } else { while (kixz + 4 <= tex2.len and con2 < uni2.len) : (kixz += 4) { uni2[con2] = @intCast(hexzNumb(tex2[kixz .. kixz + 4])); con2 += 1; } if (add != 0 and con2 > 0) uni2[con2 - 1] +%= @intCast(add); } var ind2: usize = 0; while (ind2 < con2) : (ind2 += 1) { var cptz: u21 = uni2[ind2]; if (cptz >= 0xD800 and cptz < 0xDC00 and ind2 + 1 < con2) { const lozz = uni2[ind2 + 1]; cptz = 0x10000 + ((cptz - 0xD800) << 10) + (lozz - 0xDC00); ind2 += 1; } var buf4: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(cptz, &buf4) catch continue; try outp.appendSlice(aren, buf4[0..lenz]); } return outp.toOwnedSlice(aren); }
pub fn cmapPars(aren: std.mem.Allocator, srcz: []const u8) !Cmap { var cmpz: Cmap = .{}; if (mem2.find(u8, srcz, "begincodespacerange")) |cs0z| { var cixz = cs0z; if (hexzNext(srcz, &cixz)) |lozz| cmpz.cswz = @intCast(@min(@max(lozz.len / 2, 1), 2)); } var kixz: usize = 0; while (mem2.findPos(u8, srcz, kixz, "beginbfchar")) |bstz| { const benz = mem2.findPos(u8, srcz, bstz, "endbfchar") orelse srcz.len; kixz = bstz + 11; while (cmpz.map.count() < CF.entz) { const sctz = hexzNext(srcz[0..benz], &kixz) orelse break; const dstz = hexzNext(srcz[0..benz], &kixz) orelse break; try cmpz.map.put(aren, hexzNumb(sctz), try unizEncz(aren, dstz, 0)); } kixz = benz; } kixz = 0; while (mem2.findPos(u8, srcz, kixz, "beginbfrange")) |bstz| { const benz = mem2.findPos(u8, srcz, bstz, "endbfrange") orelse srcz.len; kixz = bstz + 12; const sub = srcz[0..benz]; while (cmpz.map.count() < CF.entz) { const lotz = hexzNext(sub, &kixz) orelse break; const lozz = hexzNumb(lotz); const hitz = hexzNext(sub, &kixz) orelse break; const hizz = hexzNumb(hitz); if (hizz < lozz or hizz - lozz > CF.rngz) break; const nxtz = obje.skipWszz(sub, kixz); if (nxtz < sub.len and sub[nxtz] == '[') { kixz = nxtz + 1; var codz = lozz; while (codz <= hizz) : (codz += 1) { const dtxz = hexzNext(sub, &kixz) orelse break; try cmpz.map.put(aren, codz, try unizEncz(aren, dtxz, 0)); } const cloz = mem2.findScalarPos(u8, sub, kixz, ']') orelse sub.len; kixz = cloz + 1; } else { const dtxz = hexzNext(sub, &kixz) orelse break; var codz = lozz; while (codz <= hizz and cmpz.map.count() < CF.entz) : (codz += 1) try cmpz.map.put(aren, codz, try unizEncz(aren, dtxz, codz - lozz)); } } kixz = benz; } return cmpz; }
pub fn cmapDeco(cmpz: Cmap, aren: std.mem.Allocator, byts: []const u8, outp: *std.ArrayList(u8), cswz: u8) !u32 { var hitz: u32 = 0; var kixz: usize = 0; while (kixz < byts.len) { var codz: u32 = byts[kixz]; var stpz: usize = 1; if (cswz == 2 and kixz + 1 < byts.len) { codz = (@as(u32, byts[kixz]) << 8) | byts[kixz + 1]; stpz = 2; } kixz += stpz; if (cmpz.map.get(codz)) |tex2| { try outp.appendSlice(aren, tex2); hitz += 1; } } return hitz; }
